import { describe, it, expect } from "vitest";
import { createFreeCamera, type SceneContext } from "@babylonjs/lite";
import { attachFlyControls } from "./fly-controls.ts";

class FakeCanvas extends EventTarget {
    tabIndex = 0;
    hasAttribute() { return false; }
    setPointerCapture() {}
    releasePointerCapture() {}
}
function key(canvas: FakeCanvas, type: "keydown" | "keyup", code: string) {
    const e = new Event(type) as Event & { code: string };
    e.code = code;
    canvas.dispatchEvent(e);
}
function frame(scene: { _beforeRender: Array<(d: number) => void> }, n = 1) {
    for (let i = 0; i < n; i++) for (const f of [...scene._beforeRender]) f(16);
}

describe("attachFlyControls", () => {
    it("Shift alone does not change y; Space rises; PageDown sinks; Shift speeds up 3x", () => {
        const canvas = new FakeCanvas() as unknown as HTMLCanvasElement & FakeCanvas;
        const scene = { _beforeRender: [] as Array<(d: number) => void> } as unknown as SceneContext;
        const cam = createFreeCamera({ x: 0, y: 0, z: 0 }, { x: 0, y: 0, z: 1 });
        const dispose = attachFlyControls(cam, canvas, scene);
        const s = scene as unknown as { _beforeRender: Array<(d: number) => void> };

        key(canvas, "keydown", "ShiftLeft");
        frame(s, 60);
        expect(cam.position.y).toBe(0);
        key(canvas, "keyup", "ShiftLeft");

        key(canvas, "keydown", "KeyW");
        frame(s, 1);
        const walk = cam.position.z;
        key(canvas, "keyup", "KeyW");
        frame(s, 200);

        const z0 = cam.position.z;
        key(canvas, "keydown", "ShiftRight");
        key(canvas, "keydown", "KeyW");
        frame(s, 1);
        const boosted = cam.position.z - z0;
        key(canvas, "keyup", "KeyW");
        key(canvas, "keyup", "ShiftRight");
        frame(s, 200);
        expect(boosted / walk).toBeCloseTo(3, 1);

        const y0 = cam.position.y;
        key(canvas, "keydown", "Space");
        frame(s, 5);
        expect(cam.position.y).toBeGreaterThan(y0);
        key(canvas, "keyup", "Space");
        frame(s, 200);

        const y1 = cam.position.y;
        key(canvas, "keydown", "PageDown");
        frame(s, 5);
        expect(cam.position.y).toBeLessThan(y1);
        key(canvas, "keyup", "PageDown");
        frame(s, 200);

        dispose();
        expect(s._beforeRender.length).toBe(0);
    });

    it("cleanup removes canvas listeners", () => {
        const canvas = new FakeCanvas();
        const scene = { _beforeRender: [] as Array<(d: number) => void> } as unknown as SceneContext;
        const cam = createFreeCamera({ x: 0, y: 0, z: 0 }, { x: 0, y: 0, z: 1 });
        const dispose = attachFlyControls(cam, canvas as unknown as HTMLCanvasElement, scene);
        dispose();
        key(canvas, "keydown", "KeyW");
        const before = cam.position.z;
        frame(scene as unknown as { _beforeRender: Array<(d: number) => void> }, 5);
        expect(cam.position.z).toBe(before);
    });
});
EOF
